cookie.removeCookie(source.key);
var searchul = `${source.key}/s?q=${java.encodeURI(key)}`
var header = {
	"accept": "application/json",
	"Referer": String(searchul)
};
var hmurl = `${source.key}/user/hm.html?q=${java.encodeURI(key)}`;
//java.log(JSON.stringify(head));
var hmkey = java.get(hmurl,header).cookie("hm");
var hm = hmkey ? "hm=" + hmkey : "";
 java.log(hm);
var result = `${source.key}/user/search.html?q=${key}` + "," + JSON.stringify({
	"headers": {"Cookie": hm}
});
result;

